import{_ as t,o,c as r,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-12-export-report-file-pdf/report3_spec_en.md","filePath":"feature/admin-management/3-10-12-export-report-file-pdf/report3_spec_en.md"}'),n={name:"feature/admin-management/3-10-12-export-report-file-pdf/report3_spec_en.md"};function s(a,e,l,d,p,u){return o(),r("div",null,[...e[0]||(e[0]=[i("<p><strong>3.10.12 Export Report File PDF</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) clicks the &quot;Export PDF Report&quot; button on administrative management screens.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. System administrator authorized to export official report documents for archiving and compliance auditing.</li><li><strong>Purpose</strong>: Export A4 reports of finance, user/strike state, moderation versions and platform overview using the same definitions and timezone as their source screens. Monitoring scope remains owned by FR 3.10.3.</li><li><strong>Interface</strong>: Export PDF Report Modal (SCR-ADM-11), featuring report type selector, date range picker, data field toggles, and direct file download trigger.</li><li><strong>Data Processing</strong>: The system verifies ADMIN role authority (BR-35, BR-65), accepts report classification and temporal boundaries, queries source datasets, formats document into standard A4 PDF layout with header logo, page numbers, and timestamps, stores temporary file, and returns a secure download URL (BR-16).</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Export Report File PDF Modal (SCR-ADM-11, centered dialog window 560px):</p><ul><li>Left/Header: Modal Header title &quot;Export System PDF Report&quot; with document icon.</li><li>Center: Report type revenue/user/moderation/platform, date range, timezone UTC / Asia/Ho_Chi_Minh, sections/charts and summary preview. User report distinguishes active, converted, pardoned and expired strikes; finance report separates MRR/ARR from receipts/refunds.</li><li>Buttons: Button &quot;Download PDF File&quot; (green/navy), Button &quot;Cancel&quot;.</li><li>Footer: BrandHub confidential document notice and temporary download URL expiration timeframe (24 hours).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: reportType (enum: &quot;revenue&quot;, &quot;user&quot;, &quot;moderation&quot;, &quot;platform&quot;), startDate (YYYY-MM-DD), endDate (YYYY-MM-DD).</li><li><strong>Input optional</strong>: includeCharts, sections, timezone (UTC/Asia/Ho_Chi_Minh, default Asia/Ho_Chi_Minh), source-screen filters.</li><li><strong>System data</strong>: adminId (UUID of requesting Admin), generatedReportId (UUID), downloadUrl (temporary download link), expiresAt (24-hour expiration timestamp).</li><li><strong>Output</strong>: JSON response object containing { reportId, downloadUrl, fileName, fileSize, expiresAt } with HTTP status code 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Only ADMIN may request/export platform reports.</li><li><strong>BR-35</strong>: Verify authority before querying and before authorized download access.</li><li><strong>BR-16</strong>: Audit report type, requester, filters, period, timezone, asOf, generated file and expiry.</li><li><strong>BR-80</strong>: Match source-screen definitions in FR 3.10.2/5/6/9/11: active strike states, conversion lineage, account sanction deadlines, MRR/ARR and gross/refund/net receipts; never substitute Trust Score.</li><li><strong>BR-65</strong>: Reporting stores timestamps in UTC and supports UTC or Asia/Ho_Chi_Minh (default). Resolve date boundaries and daily/monthly buckets in the selected timezone; include timezone in responses, exports and cache keys.</li><li><strong>BR-65</strong>: Preserve A4 layout, Vietnamese glyph support, header, page numbering and secure 24-hour download URL. Do not invent historical Monitoring data or extend FR 3.10.3 scope.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>User does not possess ADMIN role permissions → Display: MSG39</li><li>No records exist within the selected date range → Display: MSG122</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin clicks &quot;Export PDF Report&quot; button on the administrative navigation bar or screen.</li><li>System displays configuration modal SCR-ADM-11.</li><li>Admin selects Report Type, specifies Date Range, and selects desired content sections.</li><li>Admin clicks &quot;Download PDF File&quot;.</li><li>System verifies administrative authority (BR-35, BR-65) and queries corresponding datasets for the selected timeframe.</li><li>System synthesizes standard A4 PDF document based on standardized template.</li><li>System generates a secure temporary download link and triggers client browser to download the PDF file to Admin workstation.</li><li>System closes modal and records the operation in the audit log (BR-16).</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: If user does not possess ADMIN role, system rejects request and displays MSG39.</li><li>5.a1: If no records exist in selected date range, system displays MSG122 and halts empty file generation.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Report PDF document is generated successfully and cached temporarily on the server for 24 hours.</li><li>Admin browser downloads PDF file to local storage.</li><li>An export audit record is persisted in audit_logs cataloging report parameters and Admin identity (BR-16).</li></ul>",14)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
